export type JsonSchemaOptions = {
  description?: string;
  default?: unknown;
  format?: string;
};

type ObjectOptions = JsonSchemaOptions & {
  required?: string[];
  optional?: readonly string[];
  additionalProperties?: boolean | JsonSchema;
  defs?: Record<string, JsonSchema>;
