const defaultFolder = "INBOX";
const defaultLimit = 20;
const mailSendAttachmentByteLimit = 25 * 1024 * 1024;

export interface MailRuntimeConfig {
  service: string;
  displayName: string;
  attachmentFallbackPrefix: string;
