          uid: moveInput.uid,
          targetFolder: moveInput.targetFolder,
          moved: true,
        };
      }
      case "delete_email": {
        const deleteInput = input as { folder?: string; uid: number };
        const folder = deleteInput.folder ?? defaultFolder;
        await protocol.deleteMessage(credential, folder, deleteInput.uid);
        return {
          folder,
          uid: deleteInput.uid,
          deleted: true,
