function createService(
  bucket: MemoryR2Bucket,
  options: { ttlSeconds?: number; maxBytes?: number } = {},
): R2TransitFileService {
  return new R2TransitFileService({
    bucket,
    publicOrigin: "http://localhost:3000",
    ttlSeconds: options.ttlSeconds ?? 60,
